CREATE TABLE IF NOT EXISTS bot_kv (namespace TEXT NOT NULL, key TEXT NOT NULL, value JSONB NOT NULL, PRIMARY KEY(namespace,key));
CREATE TABLE IF NOT EXISTS bot_plugins (name TEXT PRIMARY KEY, enabled BOOLEAN NOT NULL DEFAULT TRUE, installed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), source TEXT NOT NULL DEFAULT 'bundled');
CREATE TABLE IF NOT EXISTS bot_stats (id SMALLINT PRIMARY KEY DEFAULT 1 CHECK (id=1), messages BIGINT NOT NULL DEFAULT 0, started_at TIMESTAMPTZ, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
INSERT INTO bot_stats (id) VALUES (1) ON CONFLICT DO NOTHING;
